legacy.ruleSearchNoteUrl:
@js:(function(item) {
  if (typeof item === 'string') item = JSON.parse(item);
  var id = item.comic_id || item.id;
  if (!/^\d+$/.test(String(id))) throw new Error('再漫画搜索结果缺少作品 ID');
  return 'https://v4api.zaimanhua.com/app/v1/comic/detail/' + id + '?platform=android&timestamp=' + Math.floor(Date.now()/1000) + '&_v=2.3.0&_c=101_01_01_000';
})(result);

legacy.ruleBookContent:
@js:(function(body) {
  var response = JSON.parse(String(body));
  var data = response.data && (response.data.data || response.data);
  if (response.errno || !data) throw new Error('再漫画原站未提供正文：' + (response.errmsg || '接口无有效数据'));
  if (data.canRead === false) throw new Error('再漫画原站 canRead=false，当前章节未开放，可能需要登录、购买或版权限制');
  var pages = data.page_url || [];
  if (!pages.length) throw new Error('再漫画原站返回空图片列表');
  return pages;
})(result);

