(function(html) {
  var data = /\bvar\s+DATA\s*=\s*'([^']+)'/.exec(html);
  var assignments = /window\s*\[((?:"[a-z]+"\s*\+\s*)*"[a-z]+")\]\s*=\s*([^;]{1,2048});/g;
  var assignment, expression = '';
  while ((assignment = assignments.exec(html))) {
    if (assignment[1].replace(/["+\s]/g, '') === 'nonce') { expression = assignment[2]; }
  }
  if (!data || data[1].length > 1000000 || !expression) throw new Error('腾讯公开章节的数据结构已变化，请更新站点适配');
  var token = /\s*(?:"([a-zA-Z0-9]{0,200})"|\(\+eval\("([^"\\]{1,120})"\)\)\.toString\(\))\s*(?:\+|$)/g;
  var cursor = 0, key = '';
  while (cursor < expression.length) {
    token.lastIndex = cursor;
    var part = token.exec(expression);
    if (!part || part.index !== cursor) throw new Error('腾讯章节 nonce 表达式未支持，请更新站点适配');
    cursor = token.lastIndex;
    if (part[1] !== undefined) { key += part[1]; continue; }
    var numeric = part[2].trim();
    var substring = /^'([0-9]{1,80})'\.substring\(([0-9]{1,2})\)$/.exec(numeric);
    if (substring) { key += String(Number(substring[1].substring(Number(substring[2])))); continue; }
    numeric = numeric.replace(/!\s*window\.Array\b/g, '0').replace(/!\s*document\.children\b/g, '0')
      .replace(/document\.getElementsByTagName\('html'\)/g, '1');
    if (!/^[0-9+*\/%().<>=?! :~&|^\-]+$/.test(numeric.replace(/\bparseInt\b|\bMath\.(?:floor|round)\b/g, ''))) throw new Error('腾讯章节 nonce 数值表达式未支持');
    key += String(Number(eval(numeric)));
  }
  var markers = key.match(/\d+[a-zA-Z]+/g) || [], bytes = data[1].split('');
  while (markers.length) {
    var marker = markers.pop();
    bytes.splice(parseInt(marker, 10) & 255, marker.replace(/\d/g, '').length);
  }
  var chapter = JSON.parse(java.base64Decoder(bytes.join('')));
  if (chapter.chapter && chapter.chapter.canRead === false) throw new Error('原站要求登录、购买或验证，当前章节不可读');
  var pictures = chapter.picture || [];
  if (!pictures.length || pictures.length > 5000) throw new Error('原站没有提供可读正文图片');
  return pictures.map(function(picture) { return picture.url; });
})(String(result));
